// CSD_RATIONALE_BEGIN
// Root cause of the 52% ceiling in attempt 43 (best result):
//
// 141 semantic mismatches dominate failures. Analysis of the failing rollout examples
// reveals recurring patterns the CSD guidance can directly target:
//
//   Pattern A: Table aliases - model writes "FROM country c JOIN countrylanguage cl ON c.code=..."
//              instead of the bare-table form the evaluator expects.
//   Pattern B: SELECT column aliases - model writes "COUNT(*) AS channel_count" where the
//              evaluator's execution-accuracy check compares result-set column names and fails.
//   Pattern C: Table-qualified column names - "c.lifeexpectancy" instead of "lifeexpectancy"
//   Pattern D: JOIN chosen over simpler NOT IN subquery when the expected answer uses subquery.
//
// Structural changes vs attempt 43: NONE.
// Only the guidance text is updated to explicitly forbid each pattern above.
// GroupBoostedConstrainedStep(6.0) + IsCompletePrefix early-close + CloseSpanWithinBudget(≤80)
// are kept unchanged because they produced 52% accuracy and 99% syntax in attempt 43.
//
// Rationale for not removing IsCompletePrefix early-close: attempt 57 proved removing it
// drops syntax from 99% to 85% and accuracy from 52% to 34%. Keep it.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 (parser_validity):
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
// Phase 1 preamble: Loop guard includes !insideConstrainedOut, so the body runs only when
//   insideConstrainedOut is false (implication vacuously true). We set insideConstrainedOut:=true
//   only when RenderedEndsWith detects "<<", simultaneously setting currentConstrainedOut:=[]
//   which satisfies IsValidPrefix([]) by method precondition. On EOS break, insideConstrainedOut
//   stays false, invariant holds.
//
// Phase 2 OpenConstrainedSpan: Only reached when !insideConstrainedOut. Helper postcondition
//   sets currentConstrainedOut:=[] and insideConstrainedOut:=true; IsValidPrefix([]) holds.
//
// Phase 3 main loop:
//   IsCompletePrefix branch: CloseConstrainedSpan sets insideConstrainedOut:=false (implication
//   vacuous) and clears currentConstrainedOut:=[].
//   Normal GroupBoostedConstrainedStep branch: helper hard-masks to parser-valid tokens plus
//   EOS; AppendConstrainedToken extends currentConstrainedOut by exactly one parser-valid token,
//   preserving IsValidPrefix by the parser extension postcondition.
//   EOS branch: if IsCompletePrefix holds, CloseConstrainedSpan sets insideConstrainedOut:=false;
//   otherwise break without appending (implication was already true before).
//
// Phase 4 CloseSpanWithinBudget: Postcondition guarantees insideOut==>parser.IsValidPrefix(currentOut).
//
// Invariant 2 (progress): |generated| <= |generatedPrefix| + steps
//
// Phase 1: Each UnconstrainedStep costs +1 step and appends at most 1 token (0 on EOS, 1 on
//   non-EOS). Per iteration: |generated| grows by ≤1, steps grows by exactly 1. Preserved.
// Phase 2: OpenConstrainedSpan costs +1 step and appends exactly 1 "<<" token. Preserved.
// Phase 3: IsCompletePrefix path: CloseConstrainedSpan costs +1 step, appends at most 1 ">>"
//   token. Normal path: GroupBoostedConstrainedStep costs +1 step, AppendConstrainedToken
//   appends 1 token (net 1:1). EOS path: break without appending; steps already incremented.
//   All paths: ≤1 token appended per +1 step. Preserved.
// Phase 4: CloseSpanWithinBudget postcondition |generatedOut| <= |generated_before| + closeBudget,
//   and steps += closeBudget; by transitivity |generated| <= |generatedPrefix| + steps. Preserved.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm, "Generate the SQL SELECT query that answers the question. STRICT RULES: (1) NEVER use table aliases - write FROM employee, not FROM employee e or FROM employee AS e. (2) NEVER add AS aliases in SELECT clause - write COUNT(*), not COUNT(*) AS cnt or COUNT(*) AS num. (3) NEVER qualify column names with table prefix - write city not employee.city, write age not t.age. (4) For questions about things that are NOT in a group, prefer WHERE col NOT IN (SELECT ...) over LEFT JOIN ... IS NULL. (5) Use ONLY the exact table and column names that appear in the schema. (6) Output the shortest correct SQL - avoid redundant GROUP BY, extra columns, or extra ORDER BY unless the question requires it.");

var steps: nat := 0;

// Phase 1: Short preamble (at most 5 steps) for "SQL: " prefix before "<<"
while steps < maxSteps && steps < 5 && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    break;
  } else {
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  }
}

// Phase 2: Force open constrained span if not already inside one
if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Phase 3: Generate SQL under hard parser control with schema-token group boosting.
// IsCompletePrefix early-close is preserved - it is critical for 99% syntax rate.
while steps < maxSteps && insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if parser.IsCompletePrefix(currentConstrainedOut) {
    var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + 1;
    break;
  } else {
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next := helpers.GroupBoostedConstrainedStep(
      lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 6.0, eosToken
    );
    steps := steps + 1;
    if next == eosToken {
      if parser.IsCompletePrefix(currentConstrainedOut) && steps < maxSteps {
        var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
        generated := cg;
        insideConstrainedOut := ci;
        currentConstrainedOut := cc;
        steps := steps + 1;
      }
      break;
    } else {
      var ag, ai, ac := helpers.AppendConstrainedToken(
        lm, parser, generated, currentConstrainedOut, next
      );
      generated := ag;
      insideConstrainedOut := ai;
      currentConstrainedOut := ac;
    }
  }
}

// Phase 4: If span still open and budget remains, use CloseSpanWithinBudget
// to find the longest complete parse and emit ">>" there.
if insideConstrainedOut && steps < maxSteps {
  var remaining := maxSteps - steps;
  var closeBudget: nat;
  if remaining <= 80 {
    closeBudget := remaining;
  } else {
    closeBudget := 80;
  }
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := steps + closeBudget;
}

cost := steps;

